  ('physical-pool-games-with-friends', 'Pool games with friends', 'Take friends to a public pool and play underwater handstand and float challenges in the shallow end.', 'physical', null, 60, 'easy', 'indoors', 'medium', 'paid', 'with_friends', 10, false, false, 'Stay in the shallow end and follow lifeguard rules.', null, 'published', 'seed', now()),
  ('physical-paddleboard-taster', 'Paddleboard taster', 'Hire a paddleboard on a calm lake and learn to kneel, then stand and paddle in a straight line.', 'physical', null, 90, 'medium', 'outdoors', 'high', 'paid', 'either', 20, false, false, 'Wear a buoyancy aid and stay close to shore.', 'paddle boarding for beginners', 'published', 'seed', now()),
  ('physical-kayak-hire', 'Kayak hire', 'Rent a kayak on a river or lake and paddle out to a landmark and back. Your arms and core will feel it tomorrow.', 'physical', null, 90, 'medium', 'outdoors', 'high', 'paid', 'with_friends', 20, false, false, 'Wear a buoyancy aid and listen to the safety briefing.', null, 'published', 'seed', now()),
  ('physical-rowing-machine-2k', 'Rowing machine 2K', 'Row two thousand metres on a rowing machine, keeping a steady stroke rate. Note your time to beat next month.', 'physical', null, 12, 'hard', 'indoors', 'high', 'paid', 'alone', 35, false, false, 'Drive with legs first and keep your back straight.', 'rowing machine technique', 'published', 'seed', now()),
  ('physical-tree-pose-hold', 'Tree pose hold', 'Stand on one leg with the other foot pressed against your calf or thigh and your hands together. Hold for thirty seconds each side without hopping.', 'physical', null, 3, 'easy', 'anywhere', 'low', 'free', 'alone', 10, false, false, 'Stand near a wall in case you wobble.', null, 'published', 'seed', now()),
  ('physical-tightrope-line-walk', 'Tightrope line walk', 'Lay a strip of tape or a skipping rope straight on the floor and walk along it heel to toe, forwards and then backwards, without stepping off.', 'physical', null, 5, 'easy', 'indoors', 'medium', 'free', 'either', 10, false, false, 'Keep a hand near a wall or chair.', null, 'published', 'seed', now()),
  ('physical-kerb-free-balance-beam', 'Kerb-free balance beam', 'At a playground, walk the length of a low balance beam or log, then try it with your arms crossed.', 'physical', null, 10, 'easy', 'outdoors', 'medium', 'free', 'either', 10, false, false, 'Only use low beams close to the ground.', null, 'published', 'seed', now()),
  ('physical-single-leg-deadlift-reach', 'Single-leg deadlift reach', 'Balance on one leg and hinge forward, reaching your hands towards the floor as your back leg lifts. Eight slow reps each side.', 'physical', null, 8, 'medium', 'anywhere', 'medium', 'free', 'alone', 20, false, false, null, 'single leg deadlift bodyweight', 'published', 'seed', now()),
  ('physical-pillow-balance-stand', 'Pillow balance stand', 'Stand on a sofa cushion or folded pillow on one leg and hold for as long as you can. The wobble trains your ankles.', 'physical', null, 5, 'medium', 'indoors', 'low', 'free', 'alone', 20, false, false, 'Do it next to a wall you can grab.', null, 'published', 'seed', now()),
  ('physical-balance-while-brushing-teeth', 'Balance while brushing teeth', 'Stand on one leg for the whole time you brush your teeth, swapping legs halfway. Two minutes, twice a day.', 'physical', null, 2, 'easy', 'indoors', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('physical-flamingo-stand-off', 'Flamingo stand-off', 'Everyone stands on one leg at once. Last person with their foot still up wins and picks the next twist, like eyes closed or arms overhead.', 'physical', null, 5, 'easy', 'anywhere', 'medium', 'free', 'with_friends', 15, true, false, 'Leave plenty of space between people.', null, 'published', 'seed', now()),
  ('physical-clock-reach-balance', 'Clock reach balance', 'Stand on one leg and tap your other foot to imaginary clock positions around you: twelve, three, six, nine. Go round twice each side.', 'physical', null, 6, 'medium', 'anywhere', 'medium', 'free', 'alone', 20, false, false, null, 'star excursion balance exercise', 'published', 'seed', now()),
  ('physical-balance-board-session', 'Balance board session', 'Use a balance or wobble board for three one-minute rounds, then try a few slow squats on it.', 'physical', null, 10, 'medium', 'indoors', 'medium', 'paid', 'alone', 20, false, false, 'Use it next to a wall or rail.', 'balance board exercises for beginners', 'published', 'seed', now()),
  ('physical-slackline-try-out', 'Slackline try-out', 'String a slackline low between two strong trees and try taking three steps along it, holding a friend''s shoulder at first.', 'physical', null, 45, 'hard', 'outdoors', 'medium', 'paid', 'with_friends', 35, false, false, 'Set it up at knee height over soft grass and protect the trees.', 'how to walk a slackline for beginners', 'published', 'seed', now()),
  ('physical-eyes-closed-balance-ladder', 'Eyes-closed balance ladder', 'Balance on one foot for ten seconds with eyes open, then closed, then closed while turning your head slowly. Climb the ladder on both legs.', 'physical', null, 5, 'medium', 'indoors', 'low', 'free', 'alone', 20, false, false, 'Stand in a corner so walls are close.', null, 'published', 'seed', now()),
  ('physical-book-on-head-walk', 'Book on head walk', 'Balance a paperback on your head and walk the length of the room, turning at each end. Add a second book once you manage three laps.', 'physical', null, 5, 'easy', 'indoors', 'low', 'free', 'either', 15, true, false, null, null, 'published', 'seed', now()),
  ('physical-stepping-stone-hop', 'Stepping stone hop', 'Lay cushions across the room as stepping stones and cross from one to the next, landing softly and holding each landing for two seconds.', 'physical', null, 8, 'easy', 'indoors', 'high', 'free', 'either', 10, false, false, 'Use non-slip cushions on carpet, not a hard floor.', null, 'published', 'seed', now()),
  ('physical-single-leg-stand-with-catch', 'Single-leg stand with catch', 'Stand on one leg and toss a soft ball back and forth with a friend. Swap legs every ten catches.', 'physical', null, 10, 'easy', 'anywhere', 'medium', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('physical-heel-to-toe-sobriety-style-walk', 'Heel-to-toe sobriety style walk', 'Walk twenty steps heel to toe in a straight line, then turn and walk back the same way with your arms down at your sides.', 'physical', null, 3, 'easy', 'anywhere', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('physical-warrior-three-hold', 'Warrior three hold', 'Lean forward on one leg until your body and back leg are parallel to the floor, arms forward like a superhero. Hold for twenty seconds each side.', 'physical', null, 5, 'medium', 'anywhere', 'medium', 'free', 'alone', 20, false, false, null, 'warrior 3 pose for beginners', 'published', 'seed', now()),
  ('physical-balance-on-the-bottom-stair', 'Balance on the bottom stair', 'Stand on the edge of the bottom stair with your heels off, then lift one foot and hold. Thirty seconds each side, holding the rail lightly.', 'physical', null, 4, 'medium', 'indoors', 'low', 'free', 'alone', 20, false, false, 'Keep a hand on the rail.', null, 'published', 'seed', now()),
  ('physical-sock-on-sock-off', 'Sock on, sock off', 'Put on and take off your socks while standing on one leg, without leaning on anything. Harder than any gym move.', 'physical', null, 3, 'medium', 'indoors', 'low', 'free', 'either', 25, true, false, 'Stand near a bed you can sit on if you tip.', null, 'published', 'seed', now()),
  ('physical-balance-circuit-outdoors', 'Balance circuit outdoors', 'In a park, find a log, a low wall and a kerb-height edge and practise balancing along each for one minute.', 'physical', null, 20, 'medium', 'outdoors', 'medium', 'free', 'either', 20, false, false, 'Pick low surfaces close to the ground.', null, 'published', 'seed', now()),
  ('physical-ankle-alphabet', 'Ankle alphabet', 'Sit and trace the letters of the alphabet in the air with your big toe, once with each foot. Great for ankle mobility.', 'physical', null, 5, 'easy', 'anywhere', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('physical-hip-circles-and-leg-swings', 'Hip circles and leg swings', 'Stand by a wall and swing each leg forwards and back ten times, then side to side, then circle your hips both ways.', 'physical', null, 5, 'easy', 'anywhere', 'medium', 'free', 'alone', 10, false, false, null, 'leg swings dynamic warm up', 'published', 'seed', now()),
  ('physical-world-s-greatest-stretch', 'World''s greatest stretch', 'Learn the lunge-with-a-twist mobility move: lunge, put a hand down, rotate the other arm to the sky. Five each side.', 'physical', null, 6, 'easy', 'anywhere', 'medium', 'free', 'alone', 10, false, false, null, 'worlds greatest stretch', 'published', 'seed', now()),
  ('physical-deep-squat-sit', 'Deep squat sit', 'Sink into the deepest squat you can with heels down and just stay there for two minutes, holding a door frame if needed.', 'physical', null, 3, 'medium', 'anywhere', 'low', 'free', 'alone', 20, false, false, 'Hold onto something sturdy and stop if your knees hurt.', null, 'published', 'seed', now()),
  ('physical-thoracic-spine-opener', 'Thoracic spine opener', 'Lie on your side, knees bent, and open your top arm across to the other side like a book opening. Ten slow reps each way.', 'physical', null, 6, 'easy', 'indoors', 'low', 'free', 'alone', 10, false, false, null, 'open book stretch thoracic', 'published', 'seed', now()),
  ('physical-cat-cow-flow', 'Cat-cow flow', 'On hands and knees, slowly round your back up like a cat, then arch it down like a cow. Breathe with each move for two minutes.', 'physical', null, 3, 'easy', 'indoors', 'low', 'free', 'alone', 10, false, false, null, 'cat cow stretch', 'published', 'seed', now()),
